export const PALETTES=["rainbow","neon","pastel","sunset","ocean","candy","mono","twotone"];const d=t=>{const f=parseInt(t.slice(1),16);return[f>>16&255,f>>8&255,f&255]},M=(t,f,s)=>{t=(t%360+360)%360;const e=(1-Math.abs(2*s-1))*f,a=e*(1-Math.abs(t/60%2-1)),o=s-e/2;let n=0,c=0,r=0;return t<60?(n=e,c=a):t<120?(n=a,c=e):t<180?(c=e,r=a):t<240?(c=a,r=e):t<300?(n=a,r=e):(n=e,r=a),[Math.round((n+o)*255),Math.round((c+o)*255),Math.round((r+o)*255)]},u=(t,f)=>{const s=t.length-1,e=Math.min(s-1e-9,Math.max(0,f*s)),a=Math.floor(e),o=e-a,n=d(t[a]),c=d(t[a+1]);return[Math.round(n[0]+(c[0]-n[0])*o),Math.round(n[1]+(c[1]-n[1])*o),Math.round(n[2]+(c[2]-n[2])*o)]},h={neon:["#ff2d95","#ff7a00","#f7ff3c","#3cff8a","#22e6ff","#8b5cf6","#ff2d95"],sunset:["#ff2a4d","#ff7a2a","#ffc83c","#ff5fa8","#ff2a4d"],ocean:["#22e6ff","#3c7bff","#8b5cf6","#2ff5c3","#22e6ff"],candy:["#ff8bd1","#8affd6","#c8a6ff","#fff58a","#ffb0a0","#ff8bd1"]};export function paletteRgb(t,f,s="#ff4fd8",e="#5df2f0"){switch(f=(f%1+1)%1,t){case"neon":case"sunset":case"ocean":case"candy":return u(h[t],f);case"pastel":return M(f*360,.85,.72);case"mono":{const a=d(s),o=.55+.45*Math.sin(f*Math.PI*2);return a.map(n=>Math.round(Math.min(255,n*o+255*(1-o)*.35)))}case"twotone":{const a=d(s),o=d(e),n=.5-.5*Math.cos(f*Math.PI*2);return a.map((c,r)=>Math.round(c+(o[r]-c)*n))}default:return M(f*360,1,.58)}}export const BUCKETS=64;export function bucketOf(t){return Math.min(BUCKETS-1,Math.max(0,Math.floor((t%1+1)%1*BUCKETS)))}export function css(t,f=1){return f>=1?`rgb(${t[0]},${t[1]},${t[2]})`:`rgba(${t[0]},${t[1]},${t[2]},${f})`}
